head.script:
window.globalViewType = true;	
scwin.getType = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;
    var inputType = inputTypeList.getCellData(rowIndex, colIndex);
    switch (inputType) {
        case "radio":
            returnInfo = {
                id: "dynamic_radio_" + rowIndex + "_" + colIndex,
                inputType: "radio",
                options: {
                    groupName: "radio_" + rowIndex
                }
            }
            break;
        case "checkbox":
            returnInfo = {
                id: "dynamic_checkbox_" + rowIndex + "_" + colIndex,
                inputType: "checkbox",
                options: {}
            }
            break;
        case "button":
            returnInfo = {
                id: "dynamic_button_" + rowIndex + "_" + colIndex,
                inputType: "button",
                options: {}
            }
            break;
        case "calendar":
            returnInfo = {
                id: "dynamic_calendar_" + rowIndex + "_" + colIndex,
                inputType: "calendar",
                options: {
                    viewType: "icon",
                    dataValidCheck: true
                }
            }
            break;
        case "image":
            returnInfo = {
                id: "dynamic_image_" + rowIndex + "_" + colIndex,
                inputType: "image",
                options: {
                    imageSrc: "/SAMPLE/W5/project/dynamic/img.gif"
                }
            }
            break;
        case "link":
            returnInfo = {
                id: "dynamic_link_" + rowIndex + "_" + colIndex,
                inputType: "link",
                options: {}
            }
            break;
        case "select":
            returnInfo = {
                id: "dynamic_select_" + rowIndex + "_" + colIndex,
                inputType: "select",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList3",
                    label: "label",
                    value: "value"
                }
            }
            break;
        case "autoComplete":
            returnInfo = {
                id: "dynamic_autoComplete_" + rowIndex + "_" + colIndex,
                inputType: "autoComplete",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList3",
                    label: "label",
                    value: "value"
                }
            }
            break;
        case "checkcombobox":
            returnInfo = {
                id: "dynamic_checkcombobox_" + rowIndex + "_" + colIndex,
                inputType: "checkcombobox",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList3",
                    label: "label",
                    value: "value"
                }
            }
            break;
        case "textarea":
            returnInfo = {
                id: "dynamic_textarea_" + rowIndex + "_" + colIndex,
                inputType: "textarea",
                options: {}
            }
            break;
        case "text":
            returnInfo = {
                id: "dynamic_text_" + rowIndex + "_" + colIndex,
                inputType: "text",
                options: {}
            }
            break;
        case "textImage":
            if (globalViewType) {
                returnInfo = {
                    id: "dynamic_textImage_" + rowIndex + "_" + colIndex,
                    inputType: "textImage",
                    options: {
                        viewType: "icon",
                        imageSrc: "/SAMPLE/W5/project/dynamic/alz.jpg",
                        textAlign: "center"
                    }
                }
            } else {
                returnInfo = {
                    id: "dynamic_textImage_2_" + rowIndex + "_" + colIndex,
                    inputType: "textImage",
                    options: {
                        imageSrc: "/SAMPLE/W5/project/dynamic/alz.jpg",
                        textAlign: "center"
                    }
                }
            }
            break;
    }
    if (returnInfo) {
        console.log("[typeGetter] (" + rowIndex + ", " + colIndex + ") : " + returnInfo.inputType);
    }
    return returnInfo;
}

scwin.b1_onclick = function(e) {
    var rowIndex = WebSquare.util.getNumber(rowTb.getValue());
    gridView1.refreshRow(rowIndex);
};
scwin.b2_onclick = function(e) {
    var colIndex = WebSquare.util.getNumber(colTb.getValue());
    gridView1.refreshColumn(colIndex);
};
scwin.b3_onclick = function(e) {
    var colIndex = WebSquare.util.getNumber(cellColTb.getValue());
    var rowIndex = WebSquare.util.getNumber(cellRowTb.getValue());
    gridView1.refreshCell(rowIndex, colIndex);
};
scwin.inputTypeList_oncelldatachange = function(info) {
    gridView1.refreshCell(info.rowIndex, info.colID);
};
scwin.gridView1_oncellclick = function(row, col) {
    console.log(" row: " + row + ", col: " + col + " oncellclick : fired");
};
scwin.trigger1_onclick = function(e) {
    var options = {};
    options.type = "1";
    options.fileName = "test.xls";
    options.headerExist = "1"; //헤더의 존재 여부 입니다.
    options.startRowIndex = "0"; //excel파일에서 gird의 데이터가 시작되 row의 index입니다..(헤더 포함)
    options.startColumnIndex = "0"; //excel파일에서 gird의 데이터가 시작되는 column의 index입니다.(헤더 포함)
    options.sheetNo = 0; //excel의 sheet번호입니다.
    options.append = "0"; //append 여부입니다. 0이면 append하지 않고 새로 쓰고 1이면 그리드의 뒤쪽에 데이터를 추가로 붙여줍니다.
    options.hidden = "0"; //1이면 그리드에서 엑셀 다운로드시에 hidden을 포함했다는 의미입니다. 즉 upload시에 그리드의 hidden Column에 값을 는다는 의미입니다.
    gridView1.advancedExcelDownload(options);
};
scwin.trigger2_onclick = function(e) {
    var options = {
        fileName: "saveCSV.csv",
        type: "1",
        delim: ";"
    };
    gridView1.saveCSV(options);
};
scwin.gridView2_onviewchange = function(info) {};
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.checkColumm1 = function() {
    return WebSquare.wUnit.getDomById("gridView1_cell_0_0").innerText == "1" && WebSquare.wUnit.getDomById('gridView1_cell_1_0').innerText == "2" && WebSquare.wUnit.getDomById('gridView1_cell_2_0').innerText == "3" && WebSquare.wUnit.getDomById('gridView1_cell_3_0').innerText == "4" && WebSquare.wUnit.getDomById('gridView1_cell_4_0').innerText == "5";
}
scwin.checkColumm2 = function() {
    return WebSquare.wUnit.getDomById("gridView2_cell_0_0").innerText == "radio" && WebSquare.wUnit.getDomById('gridView2_cell_1_0').innerText == "checkbox" && WebSquare.wUnit.getDomById('gridView2_cell_2_0').innerText == "button" && WebSquare.wUnit.getDomById('gridView2_cell_3_0').innerText == "calendar" && WebSquare.wUnit.getDomById('gridView2_cell_4_0').innerText == "image";
}
scwin.checkSorted = function() {
    return WebSquare.wUnit.getDomById("gridView2_cell_8_0").innerText == "button" && WebSquare.wUnit.getDomById('gridView2_cell_9_0').innerText == "calendar" && WebSquare.wUnit.getDomById('gridView2_cell_10_0').innerText == "checkbox" && WebSquare.wUnit.getDomById('gridView2_cell_11_0').innerText == "image" && WebSquare.wUnit.getDomById('gridView2_cell_12_0').innerText == "radio";
}
