scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 상단그리드 컬럼에 위에서부터 5개row의 값(1,2,3,4,5)을 입력한다.
    //1. After executing the sample file, enter the values ​​(1,2,3,4,5) of the five rows from the top into the upper grid column.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal3()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal4()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal5()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal6()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal7()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal8()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal9()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_5_0').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. 1, 2, 3, 4, 5값이 차례대로 입력된다.
    //1. The values ​​1, 2, 3, 4, and 5 are entered in order.
    //WebSquare.wUnit.addCommand("assert", "scwin.checkColumm1()", "true");
    //Test step 2. 하단그리드 컬럼을 더블클릭하여 위에서부터 5개row의 콤보박스 속성값을 차례대로 변경한다.
    //2. Double-click the lower grid column and change the value of the combo box property of the five rows from top to bottom.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal10()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'gridView2___selectbox_col1_itemTable_0').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal11()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'gridView2___selectbox_col1_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal12()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView2___selectbox_col1_itemTable_2').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal13()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView2___selectbox_col1_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal14()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView2___selectbox_col1_itemTable_4').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. radio, checkbox, button, calendar, image 속성값이 입력되고 상단그리드의 속성도 함께 변경된다.
    //2. radio, checkbox, button, calendar, the image attribute values ​​and the input may be changed with properties of the upper grid.
    WebSquare.wUnit.addCommand("assert", "scwin.checkColumm2()", "true");
    //Test step 3. 하단그리드의 col1 헤더를 더블클릭하여 오름차순 sort한 후 상단그리드에 마우스를 오버하고 마우스스크롤을 이동한다.
    //3. Double-click the col1 header in the lower grid to sort in ascending order, then move the mouse over the upper grid and move the mouse scroll.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal15()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 3. 정상적으로 소팅된다.
    //3. Sorts normally.
    WebSquare.wUnit.addCommand("assert", "scwin.checkSorted()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.dataArr = [
        "radio", "radio",
        "checkbox", "checkbox",
        "button", "button",
        "calendar", "calendar",
        "image", "image",
        "link", "link",
        "select", "select",
        "autoComplete", "autoComplete",
        "checkcombobox", "checkcombobox",
        "textarea", "textarea",
        "text", "text",
        "textImage", "textImage"
    ];
    dataList2.setData(dataArr);
    dataList3.setData([
        "radio", "1",
        "checkbox", "2",
        "button", "3",
        "calendar", "4",
        "image", "5",
        "link", "6",
        "select", "7",
        "autoComplete", "8",
        "checkcombobox", "9",
        "textarea", "10",
        "text", "11",
        "textImage", "12"
    ]);
    window._dataArr = [];
    for (var i = 0; i < 300; i++) {
        _dataArr.push("");
    }
    dataList1.setData(_dataArr.slice(0));
    inputTypeList.setData(_dataArr.slice(0, 65));
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 27-Mar-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
